229	    protected buchungAbschliessen(): void {
230	      if (this.buchungAbschliessenDeaktiviert() || this.abschliessenLaedt()) return;
231	      const plan = this.sitzplan();
232	      if (!plan) return;
233	
234	      this.abschliessenLaedt.set(true);
235	      this.abschliessenFehler.set(null);
236	
237	      const positionen: BuchungspositionRequest[] = this.ausgewaehlteCodesListe().map((code) => ({
238	        sitzplatzCode: code,
239	        preiskategorieId: this.kategorieZuordnung().get(code)!,
240	      }));
241	
242	      this.buchungenService
243	        .buchungAnlegen(plan.veranstaltungId, {
244	          name: this.kontaktName().trim(),
245	          email: this.kontaktEmail().trim(),
246	          positionen,
247	        })
248	        .subscribe({
249	          next: (buchung) => {
250	            this.abschliessenLaedt.set(false);
251	            this.abgeschlosseneBuchung.set(buchung);
252	          },
253	          error: (fehler: HttpErrorResponse) => {
254	            this.abschliessenLaedt.set(false);
255	            this.aufBuchungsfehlerReagieren(fehler);
256	          },
257	        });
258	    }
259	
260	    private aufBuchungsfehlerReagieren(fehler: HttpErrorResponse): void {
261	      const problem = fehler.error as ProblemDetails | null;
262	      const betroffen = problem?.betroffeneSitzplaetze;
263	
264	      if (fehler.status === 409 && problem?.type === 'sitzplatz_belegt' && betroffen?.length) {
265	        this.konfliktSitzplaetze.set(betroffen);
266	        this.schritt.set(1);
267	
268	        const naechsteCodes = new Set(this.ausgewaehlteCodes());
269	        const naechsteZuordnung = new Map(this.kategorieZuordnung());
270	        for (const code of betroffen) {
271	          naechsteCodes.delete(code);
272	          naechsteZuordnung.delete(code);
273	        }
274	        this.ausgewaehlteCodes.set(naechsteCodes);
275	        this.kategorieZuordnung.set(naechsteZuordnung);
276	        if (naechsteCodes.size === 0) {
277	          this.detailsAusgeklappt.set(false);
278	        }
279	
280	        const veranstaltungId = this.sitzplan()?.veranstaltungId;
281	        if (veranstaltungId) {
282	          this.veranstaltungenService.getSitzplan(veranstaltungId).subscribe((neuerPlan) => {
283	            this.sitzplan.set(neuerPlan);
284	          });
285	        }
286	        return;
287	      }
288	
289	      this.abschliessenFehler.set(
290	        'Die Buchung konnte nicht abgeschlossen werden. Bitte versuchen Sie es erneut.',
291	      );
292	    }
293	    ```
294	    **Warum kein `catchError`/RxJS-Pipe:** Die bestehende Ladelogik im Konstruktor nutzt `catchError` für den initialen `forkJoin`-Ladevorgang; hier ist ein einzelner, durch Nutzeraktion ausgelöster POST mit zwei klar unterscheidbaren Ergebnissen (Erfolg/Fehler) — `subscribe({ next, error })` ist direkter und vermeidet eine unnötige Pipe für einen einmaligen Request ohne weitere Transformation.
295	    **Warum die Konflikt-Erkennung sowohl `fehler.status === 409` als auch `problem?.type === 'sitzplatz_belegt'` prüft:** Verlässt sich nicht allein auf den Status-Code (409 könnte theoretisch für andere Fälle wiederverwendet werden) und nicht allein auf den `type`-String (falls das Backend jemals einen anderen 4xx-Code für denselben Typ nutzt) — beide Bedingungen zusammen sind eindeutig und robust gegen künftige Erweiterungen um weitere `ProblemDetails`-Typen (z. B. `preiskategorie_ungueltig`, `sitzplatz_duplikat` aus Story 2.6), die hier bewusst in den generischen Fehlerzweig (AC #5) fallen, da keine AC dieser Story eine Sonderbehandlung dafür verlangt.
